INSERT INTO `product_attribute_values` VALUES (1,'vi','default','UNITY_ENDLESS_RUNNER_001',NULL,NULL,NULL,NULL,NULL,NULL,1,1,NULL),(2,'vi','default','Unity 3D Endless Runner Game - Source Code',NULL,NULL,NULL,NULL,NULL,NULL,1,2,NULL),(3,'vi','default','<h2>Unity 3D Endless Runner Game - Complete Source Code</h2>\n                <p>Một game endless runner 3D hoàn chỉnh được phát triển trên Unity, bao gồm đầy đủ source code, assets và documentation. Game có gameplay hấp dẫn với nhiều tính năng:</p>\n                \n                <h3>✅ Tính năng chính:</h3>\n                <ul>\n                <li>🎮 Gameplay endless runner mượt mà</li>\n                <li>🏃‍♂️ Character controller với animation đẹp mắt</li>\n                <li>🌍 Procedural level generation</li>\n                <li>💰 Coin collection system</li>\n                <li>🛍️ In-app purchase integration</li>\n                <li>📊 Leaderboard & achievements</li>\n                <li>🎵 Background music & sound effects</li>\n                <li>📱 Mobile-optimized UI</li>\n                </ul>\n                \n                <h3>🔧 Technical Details:</h3>\n                <ul>\n                <li>🎯 Unity 2022.3 LTS</li>\n                <li>💻 C# programming</li>\n                <li>📱 Ready for Android & iOS</li>\n                <li>🎨 Complete art assets included</li>\n                <li>📖 Documentation & setup guide</li>\n                <li>🛠️ Easy to customize</li>\n                </ul>',NULL,NULL,NULL,NULL,NULL,NULL,1,10,NULL),(4,'vi','default','Unity 3D Endless Runner game với đầy đủ source code, assets và documentation. Sẵn sàng publish lên Android/iOS.',NULL,NULL,NULL,NULL,NULL,NULL,1,9,NULL),(5,'vi','default',NULL,NULL,NULL,1500000.0000,NULL,NULL,NULL,1,11,NULL),(6,'vi','default','0',NULL,NULL,NULL,NULL,NULL,NULL,1,22,NULL),(7,'vi','default','1',1,1,NULL,NULL,NULL,NULL,1,8,NULL),(8,'vi','default','1',1,1,NULL,NULL,NULL,NULL,1,6,NULL),(9,'vi','default','1',1,1,NULL,NULL,NULL,NULL,1,5,NULL),