      <ul>\n                <li>🎓 Bằng Đại học Khoa học máy tính hoặc tương đương</li>\n                <li>⭐ 5+ năm kinh nghiệm Unity development</li>\n                <li>💡 Expert level C# và design patterns</li>\n                <li>📱 Shipped ít nhất 2 mobile games</li>\n                <li>🔥 Kinh nghiệm với networking, multiplayer systems</li>\n                <li>🌐 English proficiency for international collaboration</li>\n                </ul>\n                \n                <h3>🎁 Benefits Package:</h3>\n                <ul>\n                <li>💰 Lương 50-80 triệu + equity + bonuses</li>\n                <li>🏥 Premium healthcare cho cả gia đình</li>\n                <li>🏖️ 20 ngày nghỉ phép + 5 ngày sick leave</li>\n                <li>🎮 Latest MacBook Pro + gaming setup</li>\n                <li>🌟 Annual team trips + quarterly team building</li>\n                <li>📚 Learning budget 20 triệu/năm</li>\n                </ul>',NULL,NULL,NULL,NULL,NULL,NULL,4,10,NULL),(56,'vi','default','VNG tuyển Senior Unity Developer 5+ năm kinh nghiệm. Lương 50-80 triệu + equity, làm việc với team quốc tế.',NULL,NULL,NULL,NULL,NULL,NULL,4,9,NULL),(57,'vi','default',NULL,NULL,NULL,65000000.0000,NULL,NULL,NULL,4,11,NULL),(58,'vi','default','0',NULL,NULL,NULL,NULL,NULL,NULL,4,22,NULL),(59,'vi','default','1',1,1,NULL,NULL,NULL,NULL,4,8,NULL),(60,'vi','default','1',1,1,NULL,NULL,NULL,NULL,4,6,NULL),(61,'vi','default','1',1,1,NULL,NULL,NULL,NULL,4,5,NULL),(62,'vi','default','1',1,1,NULL,NULL,NULL,NULL,4,7,NULL),(63,'vi','default','Senior Unity Developer - VNG Corporation | LamGame Jobs',NULL,NULL,NULL,NULL,NULL,NULL,4,16,NULL),(64,'vi','default','VNG tuyển Senior Unity Developer 5+ năm kinh nghiệm. Lương 50-80 triệu + equity, làm việc với team quốc tế.',NULL,NULL,NULL,NULL,NULL,NULL,4,18,NULL),(65,'vi','default','game jobs, tuyển dụng game, việc làm game',NULL,NULL,NULL,NULL,NULL,NULL,4,17,NULL),(66,'vi','default','62',NULL,NULL,NULL,NULL,NULL,NULL,4,40,NULL),(67,'vi','default'